using System;using System.Linq;using System.Globalization;
namespace IdleIntelligence.Core
{
 public static class NarrativeBridge
 {
  public static StoryFacts Facts(GameState s)=>new StoryFacts{taps=s.Journal.tapsRecorded?s.Journal.measuredTaps:s.Lifetime.taps,hardwareBought=s.Lifetime.hardwareBought,users=Game.Users(s).ToDouble(),credits=s.Credits.ToDouble(),componentsEarned=s.Lifetime.componentsEarned,itemsCrafted=s.Lifetime.itemsCrafted,inventory=s.Workshop.inventory.Length,claim=PrestigeRules.Claim(s).ToDouble(),quality=s.Quality,prestiges=s.Prestige.resets,hardware=s.Hardware.Sum(),modelLevel=s.ModelLevel,researchStarted=s.Lifetime.researchStarted,completedResearch=Balance.Research.Where((d,i)=>d.Project&&s.Research[i]>0).Count(),breakthroughs=s.Industry.breakthroughs.Length,milestones=Balance.Hardware.Select((h,i)=>h.Milestones.Count(m=>s.Hardware[i]>=m.Threshold)).Sum(),axioms=s.Meta.resets,training=s.Training!=null,trainingEvent=s.Journal.Has("training-start"),research=PrestigeAutomation.ResearchJobs(s).Any(),analysis=s.Workshop.hasAnalysis,analysisEvent=s.Journal.Has("experiment-start"),crafting=s.Workshop.hasModuleJob||s.Prestige.moduleQueue.Length>0,equipped=s.Workshop.equipped.Any(v=>!string.IsNullOrEmpty(v)),server=s.Hardware[Array.FindIndex(Balance.Hardware,h=>h.Id=="server")]>=1,hardwareAuto=s.Prestige.hardwareAuto.Any(v=>v),lab=s.Prestige.lab,analysisQueue=PrestigeRules.Has(s,"F02"),analysisRepeat=MaterialAnalysis.RepeatUnlocked(s)};
  public static GameState Sync(GameState before,GameState after){if(ReferenceEquals(before,after))return after;var starting=after.Story;if(string.IsNullOrEmpty(before.Retention.aiName)&&!string.IsNullOrEmpty(after.Retention.aiName))starting=NarrativeRules.ChooseName(starting,false,after.Retention.aiName);var story=NarrativeRules.Sync(starting,Facts(before),Facts(after));if(ReferenceEquals(story,after.Story))return after;var n=after.Copy();n.Story=story;return n;}
  public static GameState Action(GameState state,string action,string value=""){var s=state.Copy();switch(action){case "guide":bool queue=PrestigeRules.Has(s,"F02"),repeat=MaterialAnalysis.RepeatUnlocked(s);if(!(value=="analysis-queue"&&queue||value=="analysis-repeat"&&repeat||value=="analysis-budget"&&(queue||repeat)))return state;s.Story=NarrativeRules.OpenGuide(s.Story,value);if(ReferenceEquals(s.Story,state.Story))return state;break;case "name":var result=NameRules.Validate(value,NameBalance.AIMaximum);if(!result.Ok||!string.IsNullOrEmpty(s.Retention.aiName))return state;s.Story=NarrativeRules.ChooseName(s.Story,false,value);s.Retention.aiName=result.Name;break;case "continue":s.Story=NarrativeRules.Continue(s.Story,Facts(s));break;case "skip":s.Story=NarrativeRules.SkipCurrent(s.Story);s.Story.legacyIntro=false;break;case "skip-tutorial":s.Story=NarrativeRules.SkipTutorial(s.Story);s.Story.legacyIntro=false;break;case "resume":s.Story=NarrativeRules.Resume(s.Story);s.Story.legacyIntro=false;break;case "toggle":s.Story=NarrativeRules.Toggle(s.Story);break;case "reopen":s.Story=NarrativeRules.Reopen(s.Story,value);break;case "chapter":s.Story=NarrativeRules.ReopenChapter(s.Story,value);break;default:return state;}return s;}
    static string Raw(ScientificNumber n){string text=n.ToDouble().ToString("R",CultureInfo.InvariantCulture).ToLowerInvariant();int at=text.IndexOf('e');if(at<0)return text;int exp=int.Parse(text.Substring(at+1),CultureInfo.InvariantCulture);if(exp>=21||exp<-6)return text.Substring(0,at)+"e"+(exp>=0?"+":"")+exp;string digits=text.Substring(0,at).Replace(".","");int point=exp+1;return point<=0?"0."+new string('0',-point)+digits:point>=digits.Length?digits+new string('0',point-digits.Length):digits.Insert(point,".");}
  public static string Text(GameState s,string id,bool title=false){var d=NarrativeCatalog.Dialogues.FirstOrDefault(v=>v.Id==id);if(d==null)return "";int l=Math.Max(0,Array.IndexOf(NarrativeCatalog.Languages,s.Settings.language));string text=title?d.Titles[l]:d.Texts[l];if(!title&&id=="tutorial-training"&&Game.IntroQuality(s))text=NarrativeCatalog.TrainingIntro[l];if(!title&&id=="tutorial-research"&&Game.IntroResearch(s))text=NarrativeCatalog.ResearchIntro[l];text=NativeCopy.Text(text,s.Settings.language);var culture=CultureInfo.GetCultureInfo(s.Settings.language);string Num(double v)=>v.ToString("#,0.##",culture);return text.Replace("{QUEUE}",IndustryBalance.AnalysisQueueCapacity.ToString(CultureInfo.InvariantCulture)).Replace("{AI}",string.IsNullOrEmpty(s.Retention.aiName)?"AURA":s.Retention.aiName).Replace("{TAP}",Num(Game.TapValue(s,s.SavedAt).ToDouble())).Replace("{USERS}",Num(Game.Users(s).ToDouble())).Replace("{HARDWARE}",s.Hardware.Sum().ToString()).Replace("{QUALITY}",s.Quality.ToString()).Replace("{EFFICIENCY}",s.Efficiency.ToString()).Replace("{ITEMS}",s.Workshop.inventory.Length.ToString()).Replace("{ITEM_SUFFIX}",s.Workshop.inventory.Length==1?"":"s").Replace("{LAST_INT}",Raw(ScientificNumber.FromData(s.Prestige.lastGain))).Replace("{INT}",Raw(PrestigeRules.Claim(s))).Replace("{LABS}",PrestigeAutomation.ResearchJobs(s).Count().ToString()).Replace("{ANALYSIS_END}",s.Workshop.hasAnalysis?DateTimeOffset.FromUnixTimeMilliseconds((long)(s.SavedAt+Math.Max(0,s.Workshop.analysis.required-s.Workshop.analysis.done)/MaterialAnalysis.Speed(s)*1000)).ToLocalTime().ToString("T",culture):DateTimeOffset.FromUnixTimeMilliseconds((long)s.SavedAt).ToLocalTime().ToString("T",culture));}
 }
}
